   660  flb_sds_t flb_msgpack_raw_to_json_sds(const void *in_buf, size_t in_size)
   661  {
   662      int ret;
   663      size_t off = 0;
   664      size_t out_size;
   665      msgpack_unpacked result;
   666      msgpack_object *root;
   667      flb_sds_t out_buf;
   668      flb_sds_t tmp_buf;
   669
   670      out_size = in_size * 1.5;
   671      out_buf = flb_sds_create_size(out_size);
   672      if (!out_buf) {
   673          flb_errno();
   674          return NULL;
   675      }
   676
   677      msgpack_unpacked_init(&result);
   678      ret = msgpack_unpack_next(&result, in_buf, in_size, &off);
   679      if (ret != MSGPACK_UNPACK_SUCCESS) {
   680          flb_sds_destroy(out_buf);
   681          return NULL;
   682      }
   683
   684      root = &result.data;
   685      while (1) {
   686          ret = flb_msgpack_to_json(out_buf, out_size, root);
   687          if (ret <= 0) {
   688              tmp_buf = flb_sds_increase(out_buf, 256);
   689              if (tmp_buf) {
   690                  out_buf = tmp_buf;
   691                  out_size += 256;
   692              }
   693              else {
   694                  flb_errno();
   695                  flb_sds_destroy(out_buf);
   696                  msgpack_unpacked_destroy(&result);
   697                  return NULL;
   698              }
   699          }
   700          else {
   701              break;
   702          }
   703      }
   704
   705      msgpack_unpacked_destroy(&result);
   706      flb_sds_len_set(out_buf, ret);
   707
   708      return out_buf;
   709  }
