    34  static flb_sds_t sds_alloc(size_t size)
    35  {
    36      void *buf;
    37      flb_sds_t s;
    38      struct flb_sds *head;
    39
    40      buf = flb_malloc(FLB_SDS_HEADER_SIZE + size + 1);
    41      if (!buf) {
    42          flb_errno();
    43          return NULL;
    44      }
    45
    46      head = buf;
    47      head->len = 0;
    48      head->alloc = size;
    49
    50      s = head->buf;
    51      *s = '\0';
    52
    53      return s;
    54  }
    55
    56  flb_sds_t flb_sds_create_len(const char *str, int len)
    57  {
    58      flb_sds_t s;
    59      struct flb_sds *head;
    60
    61      s = sds_alloc(len);
    62      if (!s) {
    63          return NULL;
    64      }
    65
    66      if (str) {
    67          memcpy(s, str, len);
    68          s[len] = '\0';
    69
    70          head = FLB_SDS_HEADER(s);
    71          head->len = len;
    72      }
    73      return s;
    74  }
